GenContFract.sub_convs_eq.code:
GenContFract.sub_convs_eq.{u_1} {K : Type u_1} {v : K} {n : ℕ} [LinearOrderedField K] [FloorRing K]
  {ifp : IntFractPair K} (stream_nth_eq : IntFractPair.stream v n = some ifp) :
  let g := of v;
  let B := (g.contsAux (n + 1)).b;
  let pB := (g.contsAux n).b;
