  {x y z : K} (ha : P.a ≠ 0) (h3 : (map φ P).roots = {x, y, z}) :
  map φ P = { a := φ P.a, b := φ P.a * -(x + y + z), c := φ P.a * (x * y + x * z + y * z), d := φ P.a * -(x * y * z) }

Cubic.disc_eq_prod_three_roots.code:
Cubic.disc_eq_prod_three_roots.{u_3, u_4} {F : Type u_3} {K : Type u_4} {P : Cubic F} [Field F] [Field K] {φ : F →+* K}
  {x y z : K} (ha : P.a ≠ 0) (h3 : (map φ P).roots = {x, y, z}) :
  φ P.disc = (φ P.a * φ P.a * (x - y) * (x - z) * (y - z)) ^ 2

